// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.voice.bargeinimport timber.log.Timberimport com.roshan.persona.voice.tts.Emotionimport com.roshan.persona.voice.tts.EmotionalTtsEngineimport com.roshan.persona.voice.tts.VoicePersonaimport java.util.concurrent.atomic.AtomicBooleanimport java.util.concurrent.atomic.AtomicLong/** * NOUS — Proactive Barge-In (§13 "NOUS Interrupts User"). * * The inverse of [BargeInDetector] — instead of detecting the user * interrupting NOUS, this class lets NOUS interrupt the *user* when an * urgent situation arises (emergency alert, critical calendar reminder, * security threat). The user was speaking; NOUS cuts them off politely * to deliver the urgent message, then resumes listening. * * ## When NOUS barges in (§13) * * Only for urgent situations, gated by [ProactiveBargeInPriority]: *  - EMERGENCY_ALERT (priority 10)  — smoke alarm, medical alert *  - SECURITY_THREAT (priority 9)   — intrusion detected, fraud alert *  - CRITICAL_REMINDER (priority 8) — meeting in 1 minute, flight boarding * * Below the [Config.threshold] (default 8), the proactive barge-in is * suppressed — the Brain should queue the message for the next natural * turn boundary instead. * * ## Flow * * ``` * User is speaking (STT active) *     ↓ * Brain detects urgent situation (priority ≥ threshold) *     ↓ * [ProactiveBargeIn.tryBargeIn] called *     ↓ * STT.stop()                               ← caller passes the stop callback *     ↓ * TTS.speak(urgent message, URGENT, persona) *     ↓ * on TTS done → STT.startRecognition(...)   ← caller passes the resume callback *     ↓ * User's interrupted speech is preserved in the STT partial buffer * ``` * * ## Politeness * * NOUS *always* apologizes for interrupting — even for EMERGENCY_ALERT. * The apology prefix is configurable in [Config] so it can be localized * and personalized per persona. Example: "Sorry to interrupt — " before * the urgent message. * * ## Cooldown * * After a proactive barge-in, we suppress further proactive barge-ins for * [Config.cooldownMs] (default 30 s). This prevents a flurry of urgent * notifications from interrupting the user back-to-back — instead, they're * coalesced into a single "you have 3 urgent alerts" message via the Brain. * * ## Testability * * The STT stop / resume callbacks are passed in by the caller (Step 5.14 * wiring), so tests can verify the barge-in decision logic without needing * a real STT engine. The [EmotionalTtsEngine] is already testable via its * [com.roshan.persona.voice.tts.TtsEngine] interface. * * @see <a href="docs/strategy/module-5-strategy-v2.md">§13 Barge-In & Interruption Handling — NOUS Interrupts User</a> */class ProactiveBargeIn(    private val tts: EmotionalTtsEngine,    private val config: Config = Config(),) {    /**     * Configuration for proactive barge-in.     *     * @param threshold    minimum priority required to trigger a proactive     *                     barge-in (default 8 = CRITICAL_REMINDER).     * @param cooldownMs   suppress further proactive barge-ins for this long     *                     after one fires (default 30 s).     * @param apologyPrefix prepended to the urgent message (e.g. "Sorry to     *                     interrupt — ").     */    data class Config(        val threshold: Int = DEFAULT_THRESHOLD,        val cooldownMs: Long = DEFAULT_COOLDOWN_MS,        val apologyPrefix: String = DEFAULT_APOLOGY,    ) {        init {            require(threshold in 1..10) { "threshold must be 1..10, got $threshold" }            require(cooldownMs in 0..300_000) {                "cooldownMs must be 0..300000, got $cooldownMs"            }        }        companion object {            /** §13: only priority 8+ triggers proactive barge-in. */            const val DEFAULT_THRESHOLD = 8            /** 30-second cooldown between proactive barge-ins. */            const val DEFAULT_COOLDOWN_MS = 30_000L            /** Default apology prefix. */            const val DEFAULT_APOLOGY = "Sorry to interrupt — "        }    }    private val inCooldown = AtomicBoolean(false)    private val lastBargeInMs = AtomicLong(0L)    /**     * Attempt a proactive barge-in.     *     * @param message      the urgent message to speak.     * @param priority     urgency 1–10 (must be ≥ [Config.threshold] to fire).     * @param persona      active voice persona.     * @param stopStt      callback to stop the in-progress STT (user was speaking).     * @param resumeStt    callback to resume STT after TTS completes.     * @return true if the barge-in fired; false if suppressed (priority too     *         low or in cooldown).     */    fun tryBargeIn(        message: String,        priority: Int,        persona: VoicePersona,        stopStt: () -> Unit,        resumeStt: () -> Unit,    ): Boolean {        require(priority in 1..10) { "priority must be 1..10, got $priority" }        if (message.isBlank()) {            Timber.tag(TAG).w("tryBargeIn called with blank message — ignoring.")            return false        }        // 1. Priority gate.        if (priority < config.threshold) {            Timber.tag(TAG).i("Proactive barge-in suppressed (priority $priority < threshold ${config.threshold}).")            return false        }        // 2. Cooldown gate.        if (inCooldown.get()) {            val elapsed = System.currentTimeMillis() - lastBargeInMs.get()            if (elapsed < config.cooldownMs) {                Timber.tag(TAG).i("Proactive barge-in suppressed (in cooldown, ${config.cooldownMs - elapsed}ms remaining).")                return false            }            inCooldown.set(false)        }        Timber.tag(TAG).i("Proactive barge-in firing (priority $priority, message len=${message.length}).")        // 3. Stop STT — the user was speaking, we're cutting them off.        stopStt()        // 4. Mark cooldown start.        val now = System.currentTimeMillis()        lastBargeInMs.set(now)        inCooldown.set(true)        // 5. Speak the urgent message with apology prefix.        val fullMessage = config.apologyPrefix + message        tts.speak(            text = fullMessage,            emotion = Emotion.URGENT,            persona = persona,            onDone = {                Timber.tag(TAG).i("Proactive barge-in TTS done — resuming STT.")                resumeStt()            },            // Proactive barge-in is itself interruptible by the user (if they            // start speaking during the urgent message, normal BargeInDetector            // fires and stops TTS — resumeStt is then called by the            // BargeInDetector's downstream wiring, not here).            onBargeIn = {                Timber.tag(TAG).i("Proactive barge-in interrupted by user — resuming STT.")                resumeStt()            },        )        return true    }    /** Force-clear the cooldown. For tests / Settings override. */    fun clearCooldown() {        inCooldown.set(false)        lastBargeInMs.set(0L)    }    /** Whether the proactive barge-in is currently in cooldown. */    val isInCooldown: Boolean get() = inCooldown.get()    private companion object {        private const val TAG = "ProactiveBargeIn"    }}// ──────────────────────────────────────────────────────────────────────────/** * Priority levels for proactive barge-in (§13). * * Higher number = more urgent. Only priorities ≥ [ProactiveBargeIn.Config.threshold] * (default 8) trigger a proactive barge-in. * * These levels are also used by the Brain (Module 2) for routing decisions: *  - priority 1–7  → queue for next natural turn boundary *  - priority 8–10 → proactive barge-in (cut off the user) */enum class ProactiveBargeInPriority(val level: Int) {    /** Informational — never barges in. */    INFO(1),    /** Low-priority notification — never barges in. */    LOW(3),    /** Normal notification — never barges in. */    NORMAL(5),    /** Important notification — never barges in (waits for turn). */    IMPORTANT(7),    /** Critical calendar reminder — barges in (e.g. meeting in 1 min). */    CRITICAL_REMINDER(8),    /** Security threat detected — barges in (e.g. intrusion, fraud). */    SECURITY_THREAT(9),    /** Emergency alert — barges in (e.g. smoke alarm, medical). */    EMERGENCY_ALERT(10);    /** True if this priority is high enough to trigger a proactive barge-in. */    fun shouldBargeIn(threshold: Int = ProactiveBargeIn.Config.DEFAULT_THRESHOLD): Boolean =        level >= threshold    companion object {        /** Get the priority enum for a numeric level, or null if unknown. */        fun fromLevel(level: Int): ProactiveBargeInPriority? =            entries.firstOrNull { it.level == level }    }}